class Solution {
  public int countDigitOne(int n) {
    long count = 0;
    for (long place = 1; place <= n; place *= 10) {
      long high = n / (place * 10), cur = n / place % 10, low = n % place;
      if (cur == 0) count += high * place;
      else if (cur == 1) count += high * place + low + 1;
      else count += (high + 1) * place;
    }
    return (int) count;
  }
}
